  function collectDraft(f){let form=$('#modal-form');if(!form)return;let v=Object.fromEntries(new FormData(form));Object.assign(editDraft,{name:v.name,label:v.label,type:v.type,costAdjustment:num(v.costAdjustment),kills:Math.max(0,num(v.kills)),startingXp:v.startingXp==null||String(v.startingXp).trim()===''?null:v.startingXp});if(gang().edition!=='N26')editDraft.subtypes=v.subtype?[v.subtype]:[];}
  function openEdit(f,draft){f=gang().fighters.find(x=>x.id===f.id)||f;init(f);editDraft=draft||{name:f.name,label:f.label||'',type:f.type,costAdjustment:num(f.costAdjustment),kills:num(f.kills),startingXp:f.startingXp??null,subtypes:[...(f.subtypes||[f.type])],specialRules:specialRulesFor(f),stats:{...f.stats}};let form=modal('Edit Fighter',editFields(f,editDraft),'Confirm',v=>{collectDraft(f);const nextStartingXp=editDraft.startingXp==null||String(editDraft.startingXp).trim()===''?null:Number(editDraft.startingXp);if(nextStartingXp!==null&&(!Number.isSafeInteger(nextStartingXp)||nextStartingXp<0))return error(window.UKI18n?.language==='en'?'Enter a whole Starting XP value of 0 or more.':'시작 XP는 0 이상의 안전한 정수로 입력하세요.');const startingXpChanged=gang().edition==='N26'&&nextStartingXp!==null&&nextStartingXp!==(f.startingXp==null?null:Number(f.startingXp)),startDelta=startingXpChanged?nextStartingXp-num(f.startingXp):0,nextXp=num(f.xp)+startDelta;if(startingXpChanged&&(!Number.isSafeInteger(num(f.xp))||!Number.isSafeInteger(nextXp)))return error(window.UKI18n?.language==='en'?'The resulting XP total is outside the supported whole-number range.':'변경 후 XP 합계가 지원하는 정수 범위를 벗어납니다.');let change=editDraft.costAdjustment-num(f.costAdjustment);if(window.MMRosterValidation){let g=gang(),candidate={...f,name:editDraft.name.trim(),subtypes:[...editDraft.subtypes]},previous=MMRosterValidation.inspect(g).find(row=>row.code==='duplicate-leader')?.leaders||0,warnings=MMRosterValidation.inspect({...g,fighters:g.fighters.map(row=>row.id===f.id?candidate:row)}).filter(row=>row.code==='duplicate-leader'&&row.leaders>previous);if(!MMRosterValidation.guardForm($('#modal-form'),g,warnings,'edit'))return false;}Object.assign(f,{name:editDraft.name.trim(),label:editDraft.label,type:editDraft.type,kills:editDraft.kills,costAdjustment:editDraft.costAdjustment,...(startingXpChanged?{startingXp:nextStartingXp}:{}),subtypes:[...editDraft.subtypes],specialRules:[...editDraft.specialRules],stats:{...editDraft.stats},cost:Math.max(0,num(f.cost)+change),xp:startingXpChanged?Math.max(0,nextXp):f.xp});if(f.ratingCost!=null)f.ratingCost=Math.max(0,num(f.ratingCost)+change);log(gang(),`${f.name}: fighter details updated`);save();});form.elements.nextRule?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();event.stopPropagation();form.querySelector('[data-fp="add-rule"]').click();}});}
