  function applyInjury(f,injury,metadata,recovery){let tsd=injury.type_specific_data||{},entry={id:id(),presetId:injury.id,name:titleOf(injury),category:injury.category||'injuries',at:now(),...metadata,typeSpecificData:{...tsd,hatred_target_kind:metadata.hatredTargetKind,hatred_target_id:metadata.hatredTargetId,hatred_target_name:metadata.hatredTargetName},addsToGlitchCount:flag(tsd.adds_to_glitch_count)};f.injuries.push(entry);let modifiers=injury.fighter_effect_modifiers||injury.modifiers||[];if(metadata.targetEquipmentId){let target=f.equipment.find(x=>x.id===metadata.targetEquipmentId);target.effects??=[];target.effects.push({id:id(),injuryId:entry.id,name:entry.name,modifiers:JSON.parse(JSON.stringify(modifiers)),typeSpecificData:{...tsd}});}else{if(injury.stat)f.effects.push({id:id(),injuryId:entry.id,name:entry.name,category:'Injury',stat:injury.stat,amount:num(injury.amount)});for(let m of modifiers)f.effects.push({id:id(),injuryId:entry.id,name:entry.name,category:'Injury',stat:statAlias[m.stat_name]||m.stat_name||m.stat,amount:num(m.numeric_value??m.default_numeric_value??m.amount),operation:m.operation});}let skill=ruleList('skills').find(x=>x.id===(tsd.skill_id||injury.granted_skill?.id));if(skill){let name=titleOf(skill);if(!f.skills.includes(name))f.skills.push(name);f.skillDetails.push({id:id(),name,cost:0,source:entry.name,injuryId:entry.id,...metadata});}if(recovery)f.status='In Recovery';if(flag(tsd.captured)){f.status='Captured';f.capturedBy=metadata.capturedBy;}if(flag(tsd.killed))f.status='Dead';if(injury.status)f.status=injury.status;if(injury.xp)f.xp=num(f.xp)+num(injury.xp);if(flag(tsd.convalescence))entry.convalescence=true;log(gang(),`${f.name}: ${entry.name}${metadata.hatredTargetName?' against '+metadata.hatredTargetName:''}`);save();}
